function addSoundFiles(files) {
	const meta = getMeta();
	files.forEach((file) => {
		const bytes = new Uint8Array(file.content);
		const name = file.name || 'sound.ogg';
		if (!Core.isOgg(bytes)) return Blockbench.showMessageBox({ title: T('sounds'), message: T('sound_invalid', name), icon: 'error' });
		if (bytes.length > Core.LIMITS.soundBytes) return Blockbench.showMessageBox({ title: T('sounds'), message: T('sound_too_big', name), icon: 'error' });
		let id = Core.sanitizeId(name);
		let n = 2;
		while (meta.sounds.find((s) => s.id === id)) id = Core.sanitizeId(name) + '_' + n++;
		meta.sounds.push({ id, ogg: Core.bytesToBase64(bytes) });
	});
	markChanged();
}
function addSoundDialog() {
	Blockbench.import({ resource_id: 'vibey_sound', extensions: ['ogg'], type: 'OGG Vorbis', multiple: true, readtype: 'buffer' }, addSoundFiles);
}
function renameItem(listKey, id) {
	const meta = getMeta();
	const item = meta[listKey].find((s) => s.id === id);
	if (!item) return;
	Blockbench.textPrompt(T('new_id'), item.id, (value) => {
		value = Core.sanitizeId(value);
		if (!value || value === item.id) return;
		if (meta[listKey].find((s) => s.id === value)) return Blockbench.showQuickMessage(T('id_taken', value), 2000);
		item.id = value;
		markChanged();
	});
}
function removeItem(listKey, id) {
	const meta = getMeta();
	meta[listKey] = meta[listKey].filter((s) => s.id !== id);
	markChanged();
}
let audio = null;
function playSound(id) {
	const s = getMeta().sounds.find((x) => x.id === id);
	if (!s) return;
	if (audio) audio.pause();
	audio = new Audio('data:audio/ogg;base64,' + s.ogg);
	audio.play().catch(() => {});
}
function spriteDialog(existingId) {
	const meta = getMeta();
	if (!Texture.all.length) return Blockbench.showQuickMessage(T('need_texture'), 2000);
	const existing = meta.sprites.find((s) => s.id === existingId);
	const texOptions = {};
	Texture.all.forEach((t) => (texOptions[Core.sanitizeId(t.name)] = t.name));
	const dialog = new Dialog({
		id: 'vibey_sprite',
		title: T('sprite_title'),
		width: 420,
		form: {
			id: { label: T('sprite_id'), type: 'text', value: existing ? existing.id : 'sparkle' },
			texture: { label: T('sprite_texture'), type: 'select', value: existing ? existing.texture : Object.keys(texOptions)[0], options: texOptions },
			uv: { label: T('sprite_uv'), type: 'vector', dimensions: 4, value: existing ? existing.uv.slice() : [0, 0, 8, 8], step: 1 },
		},
		onConfirm(r) {
			const id = Core.sanitizeId(r.id);
			if (meta.sprites.find((s) => s.id === id && s !== existing)) {
				Blockbench.showQuickMessage(T('id_taken', id), 2000);
				return false;
			}
			const sprite = { id, texture: r.texture, uv: r.uv.map(Number) };
			if (existing) Object.assign(existing, sprite);
			else meta.sprites.push(sprite);
			markChanged();
			dialog.hide();
		},
	});
	dialog.show();
}

// ------------------------------------------------------------- live link
const Link = {
	ws: null,
	state: 'off', // off | connecting | connected | error
	message: '',
	errorCode: '', // devlink_missing | bad_devlink | token_missing | unreachable | lost | token | no_welcome
	desired: false,
	attempt: 0,
	retryTimer: null,
	pingTimer: null,
	welcomeTimer: null,
	lastPong: 0,
	game: null,
	endpoint: null,
	queued: null,
	pending: [],
	requests: new Map(),
	requestCounter: 0,
	lastResult: '',
	setState(state, message) {
		this.state = state;
		this.message = message || '';
		refreshUI();
	},
	connect() {
		this.desired = true;
		this.attempt = 0;
		this.open();
	},
	disconnect() {
		this.desired = false;
		this.queued = null;
		clearTimeout(this.retryTimer);
		this.closeSocket();
		this.setState('off', T('link_off'));
	},
	closeSocket() {
		clearInterval(this.pingTimer);
		clearTimeout(this.welcomeTimer);
		const ws = this.ws;
		this.ws = null;
		if (ws) {
			ws.onclose = ws.onmessage = ws.onerror = ws.onopen = null;
			try {
				ws.close(1000);
			} catch (e) {}
		}
		this.failPending('Connection closed');
	},
	resolveEndpoint() {
		const fail = (code, message) => Object.assign(new Error(message), { code });
		if (LinkSettings.autoFind) {
			const path = Core.devlinkPath(gameDir(), pathSep());
			const text = readTextFile(path);
			if (text == null) throw fail('devlink_missing', T('devlink_missing', path));
			let d;
			try {
				d = Core.parseDevlink(text);
			} catch (e) {
				throw fail('bad_devlink', path + ': ' + e.message);
			}
			return { port: d.port, token: d.token, source: path };
		}
		if (!LinkSettings.token) throw fail('token_missing', T('token_missing'));
		return { port: Number(LinkSettings.port) || 47821, token: LinkSettings.token, source: 'manual' };
	},
	open() {
		clearTimeout(this.retryTimer);
		this.closeSocket();
		let ep;
		try {
			ep = this.resolveEndpoint();
		} catch (e) {
			return this.scheduleRetry(e.message, e.code || 'unreachable');
		}
		this.endpoint = ep;
		this.setState('connecting', T('link_connecting', '127.0.0.1:' + ep.port));
		let ws;
		try {
			ws = new WebSocket('ws://127.0.0.1:' + ep.port);
		} catch (e) {
			return this.scheduleRetry(e.message, 'unreachable');
		}
		this.ws = ws;
		ws.onopen = () => {
			this.send({ type: 'hello', token: ep.token, client: 'blockbench-vibey', version: VERSION });
			this.welcomeTimer = setTimeout(() => {
				if (this.ws === ws && this.state !== 'connected') {
					this.closeSocket();
					this.scheduleRetry(T('link_no_welcome'), 'no_welcome');
				}
			}, 5000);
		};
		ws.onmessage = (ev) => this.onMessage(ev.data);
		ws.onerror = () => {};
		ws.onclose = (ev) => this.onClose(ev, ws);
	},
	onClose(ev, ws) {
		if (ws !== this.ws) return;
		const wasConnected = this.state === 'connected';
		this.ws = null;
		clearInterval(this.pingTimer);
		clearTimeout(this.welcomeTimer);
		this.failPending('Connection closed');
		if (ev.code === 4001) {
			this.desired = false;
			this.errorCode = 'token';
			return this.setState('error', T('link_token_rejected'));
		}
		if (!this.desired) return this.setState('off', T('link_off'));
		this.scheduleRetry(wasConnected ? T('link_lost') : T('link_unreachable', this.endpoint ? this.endpoint.port : LinkSettings.port), wasConnected ? 'lost' : 'unreachable');
	},
	scheduleRetry(message, code) {
		this.errorCode = code || 'unreachable';
		if (!this.desired) return this.setState('error', message);
		const delay = Core.backoffDelay(this.attempt++);
		this.setState('error', message + T('link_retry', Math.round(delay / 100) / 10));
		clearTimeout(this.retryTimer);
		this.retryTimer = setTimeout(() => this.desired && this.open(), delay);
	},
	send(obj) {
		if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(obj));
	},
	onMessage(data) {
		let msg;
		try {
			msg = JSON.parse(data);
		} catch (e) {
			return;
		}
		// answers to request() (submit, submissions, withdraw) carry the requestId
		if (msg.requestId && this.requests.has(msg.requestId)) {
			const r = this.requests.get(msg.requestId);
			this.requests.delete(msg.requestId);
			clearTimeout(r.timer);
			r.resolve(msg);
			return;
		}
		if (msg.type === 'submission' && msg.submission) {
			Blockbench.showQuickMessage(T('submission_update', msg.submission.name || msg.submission.id, statusLabel(msg.submission.status)), 4000);
			return;
		}
		switch (msg.type) {
			case 'welcome': {
				clearTimeout(this.welcomeTimer);
				this.attempt = 0;
				this.errorCode = '';
				this.game = msg;
				this.lastPong = Date.now();
				this.setState('connected', T('link_connected', msg.game || '?', msg.player || '?'));
				clearInterval(this.pingTimer);
				this.pingTimer = setInterval(() => {
					if (Date.now() - this.lastPong > 25000 && this.ws) {
						const ws = this.ws;
						this.onClose({ code: 1006 }, ws);
						try {
							ws.close();
						} catch (e) {}
						return;
					}
					this.send({ type: 'ping' });
				}, 10000);
				const q = this.queued;
				this.queued = null;
				if (q) this.push(q.action);
				break;
			}
			case 'pong':
				this.lastPong = Date.now();
				break;
			case 'pushed':
			case 'error': {
				const idx = this.pending.findIndex((p) => p.id === msg.id);
				const p = idx >= 0 ? this.pending.splice(idx, 1)[0] : msg.type === 'pushed' ? this.pending.shift() : null;
				if (p) {
					clearTimeout(p.timer);
					p.resolve(msg);
				} else if (msg.type === 'error') {
					this.lastResult = msg.message || 'error';
					Blockbench.showQuickMessage('Vibey: ' + (msg.message || 'error'), 3000);
					refreshUI();
				}
				break;
			}
			case 'log':
				console[msg.level === 'warn' ? 'warn' : 'log']('[Vibey game] ' + msg.message);
				if (msg.level === 'warn') Blockbench.showQuickMessage('Vibey: ' + msg.message, 2500);
				break;
		}
	},
	failPending(reason) {
		const reqs = [...this.requests.values()];
		this.requests.clear();
		reqs.forEach((r) => {
			clearTimeout(r.timer);
			r.resolve({ type: 'error', message: reason });
		});
		const list = this.pending;
		this.pending = [];
		list.forEach((p) => {
			clearTimeout(p.timer);
			p.resolve({ type: 'error', id: p.id, message: reason });
		});
	},
	/** Pushes the open project. action: equip | play | none. Resolves with the game's answer. */
	push(action, opts) {
		opts = opts || {};
		if (!isVibey()) return Promise.resolve(null);
		const r = buildBundle();
		if (r.errors.length) {
			if (opts.auto) {
				this.lastResult = T('push_invalid', r.errors.length);
				refreshUI();
			} else showProblems(T('push_blocked'), r);
			return Promise.resolve({ type: 'error', message: 'invalid bundle', errors: r.errors });
		}
		const text = JSON.stringify({ type: 'push', bundle: r.bundle, action });
		if (Core.utf8Length(text) > Core.LIMITS.messageBytes) {
			showFriendly({ key: 'too_big', icon: 'sd_card_alert', details: T('push_too_big') + ' (' + Math.round(Core.utf8Length(text) / 1024) + ' KiB)' });
			return Promise.resolve({ type: 'error', message: 'too big' });
		}
		if (this.state !== 'connected' || !this.ws) {
			if (opts.auto) return Promise.resolve(null);
			this.queued = { action };
			if (!this.desired || this.state === 'error') this.connect();
			Blockbench.showQuickMessage(T('push_queued'), 2000);
			return Promise.resolve({ type: 'queued' });
		}
		const id = r.bundle.id;
		const project = Project;
		this.ws.send(text);
		this.lastResult = T('push_sent', id);
		refreshUI();
		return new Promise((resolve) => {
			const p = { id, resolve, timer: null };
			p.timer = setTimeout(() => {
				this.pending = this.pending.filter((x) => x !== p);
				resolve({ type: 'error', id, message: 'timeout', timeout: true });
			}, 10000);
			this.pending.push(p);
		}).then((res) => {
			if (res.type === 'pushed' && res.ok !== false) {
				this.lastResult = T('push_ok', id) + (res.warnings && res.warnings.length ? ' (' + res.warnings.length + ' ' + T('warnings') + ')' : '');
				sessionOf(project).pushed = true;
				if (!opts.auto) Blockbench.showQuickMessage(T('live_sent'), 2500);
				if (res.warnings && res.warnings.length) res.warnings.forEach((w) => console.warn('[Vibey game] ' + w));
			} else if (res.timeout) {
				this.lastResult = T('push_timeout', id);
				if (!opts.auto) showFriendly({ key: 'timeout', icon: 'hourglass_empty', details: this.lastResult, buttons: [{ label: T('fe_try_again'), action: () => testLive() }] });
				else Blockbench.showQuickMessage(this.lastResult, 2500);
			} else if (/^Connection closed$/.test(res.message || '')) {
				this.lastResult = T('link_lost');
				if (!opts.auto) showLinkProblem({ code: 'lost' });
			} else {
				this.lastResult = T('push_failed', id, res.message || res.error || '?');
				showFriendly({ key: 'game_rejected', icon: 'report', args: [id], details: (res.message || res.error || '?') + ((res.errors && res.errors.length) ? '\n' + res.errors.join('\n') : ''), buttons: [{ label: T('menu_validation'), action: validateNow }] });
			}
			refreshUI();
			return res;
		});
	},
	remove(id) {
		this.send({ type: 'remove', id });
	},
	/** Sends msg with a fresh requestId; resolves with the game's answer ({type: 'error', message} on timeout/offline). */
	request(msg, timeoutMs) {
		if (this.state !== 'connected' || !this.ws) return Promise.resolve({ type: 'error', message: T('submit_need_link') });
		const requestId = 'r' + ++this.requestCounter;
		const text = JSON.stringify(Object.assign({}, msg, { requestId }));
		if (Core.utf8Length(text) > Core.LIMITS.messageBytes) return Promise.resolve({ type: 'error', message: T('push_too_big') });
		return new Promise((resolve) => {
			const timer = setTimeout(() => {
				this.requests.delete(requestId);
				resolve({ type: 'error', message: 'timeout', timeout: true });
			}, timeoutMs || 20000);
			this.requests.set(requestId, { resolve, timer });
			this.ws.send(text);
		});
	},
};
// ------------------------------------------------------------- Submit to Vibe (VIBE-API-2 §3, through the game)
const statusLabel = (s) => (STRINGS['status_' + s] ? T('status_' + s) : String(s || '?'));

/** Viewport screenshot scaled into a 256×256 PNG (base64), or null. */
function viewportThumbnail() {
	return new Promise((resolve) => {
		try {
			const finish = (dataUrl) => {
				if (!dataUrl) return resolve(null);
				const img = new Image();
				img.onload = () => {
					const c = document.createElement('canvas');
					c.width = c.height = 256;
					const g = c.getContext('2d');
					const s = Math.min(img.width, img.height);
					g.drawImage(img, (img.width - s) / 2, (img.height - s) / 2, s, s, 0, 0, 256, 256);
					resolve(c.toDataURL('image/png').replace(/^data:image\/png;base64,/, ''));
				};
				img.onerror = () => resolve(null);
				img.src = dataUrl;
			};
			const preview = typeof Preview !== 'undefined' ? Preview.selected : null;
			if (!preview) return resolve(null);
			if (typeof Screencam !== 'undefined' && Screencam.screenshotPreview) {
				Screencam.screenshotPreview(preview, { crop: false }, finish);
			} else {
				preview.render && preview.render();
				finish(preview.canvas && preview.canvas.toDataURL('image/png'));
			}
		} catch (e) {
			console.warn('[Vibey] thumbnail failed', e);
			resolve(null);
		}
	});
}

function ensureLinked(retry) {
	if (Link.state === 'connected') return true;
	if (Link.state === 'off' || Link.state === 'error') Link.connect();
	showLinkProblem({ message_override: T('fe_need_game_msg'), retry: retry || submitDialog });
	return false;
}
/** Friendly dialog for a failed submit / submissions / withdraw answer from the game. */
function showSubmitProblem(res, retry) {
	const message = (res && (res.message || res.error || res.type)) || '?';
	const kind = Core.linkErrorKind(res && res.timeout ? 'timeout' : '', message);
	if (kind === 'not_signed_in' || kind === 'timeout') {
		return showFriendly({ key: kind, icon: kind === 'timeout' ? 'hourglass_empty' : 'person_off', details: message, buttons: [{ label: T('fe_try_again'), action: retry }] });
	}
	if (Link.state !== 'connected') return showLinkProblem({ code: 'lost', details: message, retry });
	return showFriendly({ key: 'submit_failed', icon: 'cloud_off', details: message, buttons: [{ label: T('fe_try_again'), action: retry }] });
}

function submitDialog() {
	if (!isVibey()) return testLive();
	if (!ensureLinked(submitDialog)) return;
	const project = Project;
	const r = buildBundle();
	if (r.errors.length) return showProblems(T('push_blocked'), r);
	const dialog = new Dialog({
		id: 'vibey_submit',
		title: T('submit_title'),
		width: 520,
		lines: ['<p style="opacity:.8">' + esc(T('submit_intro')) + '</p>'],
		form: {
			name: { label: T('submit_name'), type: 'text', value: (r.bundle.name && r.bundle.name.en) || '' },
			description: { label: T('submit_description'), type: 'textarea', value: (r.bundle.description && r.bundle.description.en) || '' },
			thumbnail: { label: T('submit_thumbnail'), type: 'checkbox', value: true },
		},
		async onConfirm(form) {
			let msg;
			try {
				const thumbnail = form.thumbnail ? await viewportThumbnail() : null;
				msg = Core.submitMessage({ bundle: r.bundle, name: form.name, description: form.description, thumbnail });
			} catch (e) {
				showFriendly({ key: 'submit_failed', icon: 'edit_note', message: T('submit_failed', e.message), fixes: [], details: e.message });
				return;
			}
			Blockbench.showQuickMessage(T('submit_sending', msg.name), 1500);
			const res = await Link.request(msg, 30000);
			if (res.type === 'submitted' && res.submission) {
				sessionOf(project).submitted = true;
				refreshUI();
				Blockbench.showMessageBox({ title: T('submit_title'), message: T('submit_ok', res.submission.name || msg.name, statusLabel(res.submission.status)), icon: 'check' });
			} else {
				showSubmitProblem(res, submitDialog);
			}
		},
	});
	dialog.show();
}

async function submissionsDialog() {
	if (!ensureLinked(submissionsDialog)) return;
	const res = await Link.request({ type: 'submissions' }, 20000);
	if (res.type !== 'submissions') {
		showSubmitProblem(res, submissionsDialog);
		return;
	}
	const list = Array.isArray(res.submissions) ? res.submissions : [];
	const rows = list.length
		? list.map((s) => {
			const open = Core.SUBMISSION_STATUS[s.status] && Core.SUBMISSION_STATUS[s.status].open;
			return '<tr><td>' + esc(s.name || s.bundleId || s.id) + '</td><td>' + esc(s.kind || '') + (s.slot ? ' / ' + esc(s.slot) : '') + '</td><td>' + esc(statusLabel(s.status))
				+ (s.reason ? '<br><small>' + esc(s.reason) + '</small>' : '') + (s.itemId ? '<br><small>' + esc(s.itemId) + '</small>' : '') + '</td><td>'
				+ (open ? '<button class="vibey-withdraw" data-id="' + esc(s.id) + '">' + esc(T('withdraw')) + '</button>' : '') + '</td></tr>';
		}).join('')
		: '<tr><td colspan="4">' + esc(T('submissions_empty')) + '</td></tr>';
	const dialog = new Dialog({
		id: 'vibey_submissions',
		title: T('submissions'),
		width: 640,
		singleButton: true,
		lines: ['<table style="width:100%;border-collapse:collapse" class="vibey-submissions">' + rows + '</table>'],
	});
	dialog.show();
	setTimeout(() => {
		document.querySelectorAll('#vibey_submissions .vibey-withdraw, .vibey-submissions .vibey-withdraw').forEach((b) => {
			b.onclick = async () => {
				b.disabled = true;
				const r = await Link.request({ type: 'withdraw', submissionId: b.getAttribute('data-id') }, 20000);
				b.textContent = r.type === 'withdrawn' ? T('withdrawn_ok') : (r.message || 'error');
			};
		});
	}, 50);
}

// ------------------------------------------------------------- friendly errors
/**
 * A plain-language error dialog: what happened, numbered steps to fix it, and the technical text folded away under
 * "Details". opts: { key (fe_<key>_title/_msg/_fix), title, message, fixes: [], details, extra, icon, args,
 * buttons: [{label, action}] } – the last button closes.
 */
function showFriendly(opts) {
	const key = opts.key;
	const title = opts.title || T('fe_' + key + '_title', ...(opts.args || []));
	const message = opts.message || T('fe_' + key + '_msg', ...(opts.args || []));
	const fixes = opts.fixes || (STRINGS['fe_' + key + '_fix'] ? T('fe_' + key + '_fix').split('\n') : []);
	const buttons = (opts.buttons || []).concat([{ label: T('fe_close') }]);
	let html = '<div class="vibey_friendly"><div class="vf_head"><i class="material-icons vf_icon">' + esc(opts.icon || 'sentiment_dissatisfied') + '</i><div>'
		+ '<div class="vf_title">' + esc(title) + '</div><div class="vf_msg">' + esc(message) + '</div></div></div>';
	if (fixes.length) html += '<div class="vf_fix"><div class="vf_label">' + esc(T('fe_fix')) + '</div><ol>' + fixes.map((f) => '<li>' + esc(f) + '</li>').join('') + '</ol></div>';
	if (opts.extra) html += '<div class="vf_extra">' + esc(opts.extra) + '</div>';
	if (opts.details) html += '<details class="vf_details"><summary>' + esc(T('fe_details')) + '</summary><pre>' + esc(opts.details) + '</pre></details>';
	html += '</div>';
	if (Dialog.open && Dialog.open.id === 'vibey_friendly') Dialog.open.close(Dialog.open.cancelIndex);
	const dialog = new Dialog({
		id: 'vibey_friendly',
		title: 'Vibey',
		width: 540,
		lines: [html],
		buttons: buttons.map((b) => b.label),
		confirmIndex: 0,
		cancelIndex: buttons.length - 1,
		onButton(i) {
			const b = buttons[i];
			if (b && typeof b.action === 'function') setTimeout(b.action, 0);
		},
	});
	dialog.vibey_key = key;
	dialog.show();
	return dialog;
}
/** Friendly "can't reach the game" (and friends) for the current live link error. */
function showLinkProblem(opts) {
	opts = opts || {};
	const kind = Core.linkErrorKind(opts.code || Link.errorCode, opts.message || Link.message);
	const icons = { token: 'key_off', timeout: 'hourglass_empty', not_signed_in: 'person_off', lost: 'link_off' };
	return showFriendly({
		key: kind,
		icon: icons[kind] || 'wifi_off',
		message: opts.message_override,
		extra: opts.keepsTrying ? T('fe_keeps_trying') : '',
		details: [opts.details, Link.message, 'devlink.json: ' + Core.devlinkPath(gameDir(), pathSep())].filter(Boolean).join('\n'),
		buttons: [
			{ label: T('fe_try_again'), action: opts.retry || (() => testLive()) },
			{ label: T('fe_open_settings'), action: openLinkSettings },
		],
	});
}
/** Validation problems as a friendly list (fix text first, technical message under Details). */
function friendlyList(messages) {
	return messages.map((m) => {
		const f = Core.friendlyProblem(m);
		return { text: f ? T(f.key, ...f.args) : m, raw: m, key: f ? f.key : '' };
	});
}

