const RARITY_OPTIONS = () => ({ common: T('rarity_common'), rare: T('rarity_rare'), epic: T('rarity_epic'), legendary: T('rarity_legendary') });
const thumbSrc = (name) => (Core.ASSETS.thumbs && Core.ASSETS.thumbs[name] ? 'data:image/png;base64,' + Core.ASSETS.thumbs[name] : '');
function wizardTemplates(kind, slot) {
	const list = (Core.ASSETS.templates && Core.ASSETS.templates[kind === 'emote' ? 'emote' : slot]) || [];
	return list.map((t) => ({ key: t.key, name: (isGerman() && t.name.de) || t.name.en, thumb: thumbSrc(t.key) }));
}
/** Encodes template pixels through a canvas (compressed PNG, much smaller than the raw encoder). */
function canvasEncode(img) {
	try {
		const c = document.createElement('canvas');
		c.width = img.width;
		c.height = img.height;
		const ctx = c.getContext('2d');
		const data = ctx.createImageData(img.width, img.height);
		data.data.set(img.data);
		ctx.putImageData(data, 0, 0);
		return c.toDataURL('image/png').split(',')[1];
	} catch (e) {
		return Core.bytesToBase64(Core.encodePng(img));
	}
}
/**
 * Creates the project for a finished wizard (also used by the tests). opts: { kind, slot, name: {en, de}, id,
 * author, rarity, loop, length, stopOnMove, template ('' = empty | starter key) }. Returns the new project.
 */
function createItem(opts) {
	const kind = opts.kind === 'emote' ? 'emote' : 'cosmetic';
	const id = String(opts.id || Core.wizardId(prefs().namespace, opts.name && opts.name.en, kind)).trim();
	const common = { id, name: opts.name || { en: '' }, author: opts.author || '', rarity: opts.rarity || 'common', template: opts.template };
	let snap;
	const tpl = opts.template && ((Core.ASSETS.templates || {})[kind === 'emote' ? 'emote' : opts.slot] || []).find((t) => t.key === opts.template);
	if (tpl) snap = Core.templateSnapshot(tpl.bundle, common);
	else {
		snap = Core.starterSnapshot(Object.assign({}, common, { kind, slot: opts.slot, loop: !!opts.loop, length: opts.length, stopOnMove: opts.stopOnMove }));
		snap.textures.forEach((t) => {
			if (!t.template) return;
			const kindName = t.id === 'cape' || t.id === 'shield' ? t.id : 'model';
			t.png = canvasEncode(Core.templateImage(kindName, t.uvWidth, t.uvHeight));
		});
	}
	setupProject(kind === 'emote' ? Formats[EMOTE] : Formats[COSMETIC]);
	applySnapshot(snap);
	Project.saved = false;
	const meta = getMeta();
	meta.tutorial = { step: 0, done: {} };
	// remember how the template texture looks, so the guide can tell when it was painted
	if (!tpl && Texture.all.length) {
		const tex = Texture.all.find((t) => t.use_as_default) || Texture.all[0];
		const capture = (tries) => {
			const h = canvasPixelHash(tex);
			if (h && tex.width) meta.wizard.textureHash = h;
			else if (tries > 0) setTimeout(() => capture(tries - 1), 50);
		};
		capture(100);
	}
	if (kind === 'emote' && Animator.animations[0]) Animator.animations[0].select && Animator.animations[0].select();
	savePrefs({ namespace: id.split(':')[0], author: opts.author || prefs().author || '' });
	if (prefs().guide !== false) Guide.show(false);
	const view = CAMERA[kind === 'emote' ? 'emote' : snap.meta.slot] || CAMERA.emote;
	if (Preview.selected && Preview.selected.loadAnglePreset) Preview.selected.loadAnglePreset({ position: view[0], target: view[1] });
	refreshUI();
	if (typeof Validator !== 'undefined') Validator.validate();
	return Project;
}

